}

* {
  box-sizing: border-box;
}

html {
  color-scheme: light;
}

body {
  margin: 0;
  min-height: 100vh;
  background: var(--creator-bg);
  color: var(--creator-text);
  font-family: var(--font-body);
}

:root {
  --canvas-sidebar-bg: color-mix(in oklab, var(--bg-elevated) 86%, transparent);
  --canvas-tooltip-bg: color-mix(in oklab, var(--bg-elevated) 94%, transparent);
