  --canvas-grid-color: color-mix(in oklab, var(--accent-primary) 10%, transparent);
  --canvas-node-highlight-bg: color-mix(in oklab, var(--canvas-node-bg) 80%, var(--accent-primary));
  --shadow-node: var(--shadow-md);
  --minimap-bg: color-mix(in oklab, var(--bg-elevated) 92%, transparent);
  --minimap-mask: color-mix(in oklab, var(--bg-primary) 45%, transparent);
  --minimap-node: color-mix(in oklab, var(--text-muted) 35%, transparent);
  --rel-focus-border: color-mix(in oklab, var(--accent-primary) 52%, transparent);
  --rel-focus-text: var(--accent-text);
  --rel-focus-bg: color-mix(in oklab, var(--accent-primary) 16%, transparent);
  --rel-ancestor-border: var(--rel-parent-border);
  --rel-ancestor-text: var(--rel-parent-text);
  --rel-ancestor-bg: var(--rel-parent-bg);
  --rel-descendant-border: var(--rel-child-border);
  --rel-descendant-text: var(--rel-child-text);
  --rel-descendant-bg: var(--rel-child-bg);
  --rel-default-border: var(--border-default);
  --rel-default-text: var(--text-muted);
  --rel-default-bg: color-mix(in oklab, var(--bg-elevated) 72%, transparent);
}

a {
  color: inherit;
  text-decoration: none;
}

/* The global anchor reset intentionally inherits surrounding copy color. Keep
   explicit high-contrast link utilities authoritative on dark action surfaces. */
a.text-white {
  color: #ffffff;
}

.pilot-cream-cta {
  color: #2e322d;
}

h1,
h2,
h3,
h4,
h5,
h6 {
  color: var(--text-primary);
  font-family: var(--font-heading);
  margin: 0;
}

p {
  margin: 0;
}

button,
input,
select,
textarea {
  font: inherit;
}

