  border: 1px solid var(--creator-border) !important;
  box-shadow: none !important;
}

.react-flow__controls-button {
  background: var(--creator-surface) !important;
  border-bottom: 1px solid var(--creator-border) !important;
  fill: var(--creator-text-muted) !important;
}

.react-flow__controls-button:hover {
  background: var(--creator-surface-muted) !important;
